import{_ as t,c as i,o as a,ag as n}from"./chunks/framework.Ci10AEOF.js";const c=JSON.parse('{"title":"Web Administrator","description":"What the browser-based administrator is, and where its documentation lives","frontmatter":{"title":"Web Administrator","description":"What the browser-based administrator is, and where its documentation lives"},"headers":[],"relativePath":"engine/web_administrator.md","filePath":"engine/web_administrator.md","lastUpdated":1793057853000}'),o={name:"engine/web_administrator.md"};function r(s,e,d,l,h,p){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="web-administrator" tabindex="-1">Web Administrator <a class="header-anchor" href="#web-administrator" aria-label="Permalink to &quot;Web Administrator&quot;">​</a></h1><p>OIE can be administered from a browser. The web administrator is a read/write client.</p><p>It is a separate application that connects to a running engine. It runs on its own under Node.js or Docker, or as a WAR deployed into the engine, in which case the engine&#39;s own web server serves it on the engine&#39;s existing port, behind the same credentials. It works against the same REST API as the desktop Administrator, so both can be pointed at one engine at the same time. It is open source under MPL 2.0.</p><p>The <strong>Web Support</strong> extension is optional. Without it the web administrator works as a client of the engine&#39;s REST API. Installing it adds message-tree serialization, engine-side JavaScript validation, plugin interfaces served by the engine, and an embedded WAR. It installs like any other extension (see the <a href="./plugins.html">Plugin Guide</a>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The web client&#39;s README gives OIE 4.6.0 as its minimum engine version.</p></div><p>With the WAR deployed into the engine, browse to <code>https://&lt;host&gt;:8443/oie-webadmin/</code>.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The web administrator is developed outside the engine repository, and its documentation is in its own repositories:</p><p><a href="https://github.com/gibson9583/oie-web-client" target="_blank" rel="noreferrer">gibson9583/oie-web-client</a> holds the administrator itself: what it covers, and standalone Node.js, Docker, and <a href="https://github.com/gibson9583/oie-web-client#deploy-into-an-existing-oie-server-war" target="_blank" rel="noreferrer">WAR</a> deployment. <a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">gibson9583/oie-web-support-plugin</a> holds the optional Web Support extension, its releases, and its installation notes. For writing a web interface for an extension, and the extension points available to it, see <a href="https://github.com/gibson9583/oie-web-client/blob/main/web-administrator/PLUGINS.md" target="_blank" rel="noreferrer">PLUGINS.md</a>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./accessing_the_administrator.html">Accessing the Administrator</a></li><li><a href="./desktop_administrator.html">Desktop Administrator</a></li><li><a href="./plugins.html">Plugin Guide</a></li></ul>',11)]))}const b=t(o,[["render",r]]);export{c as __pageData,b as default};
